package org.brightstats.stats;

import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.function.IntConsumer;
import com.google.gson.*;
import org.apache.commons.math3.distribution.NormalDistribution;

/** Paired-case bootstrap vanishing-tetrad assessment of individual measurement blocks. */
public final class TetradAnalysis {
    private TetradAnalysis(){}
    public enum Selection {CANONICAL_BASIS,REFERENCE_SUBSET,ALL_TETRADS;@Override public String toString(){return switch(this){case CANONICAL_BASIS->"Canonical algebraic basis";case REFERENCE_SUBSET->"Reference subset (includes 14-indicator quirk)";case ALL_TETRADS->"All tetrads (includes redundancies)";};}}
    public record Options(int samples,long seed,double significance,RegressionBootstrap.Convention convention,boolean twoSided,Selection selection,boolean retainDraws){
        public Options{Objects.requireNonNull(convention);Objects.requireNonNull(selection);if(samples<30||samples>100000||!Double.isFinite(significance)||significance<=0||significance>=1)throw new IllegalArgumentException("Tetrad analysis needs 30–100000 samples and significance strictly between zero and one.");if(!twoSided&&(convention==RegressionBootstrap.Convention.STANDARD||significance>=.5))throw new IllegalArgumentException("One-tailed tetrad compatibility requires reference inference and significance below 0.5.");}
        public static Options defaults(){return new Options(5000,ReferenceResampling.DEFAULT_SEED,.05,RegressionBootstrap.Convention.STANDARD,true,Selection.CANONICAL_BASIS,false);}
    }
    public record Tetrad(int id,int a,int b,int c,int d){}
    public record Term(Tetrad tetrad,String label,double original,double mean,double standardDeviation,double statistic,double pValue,double bonferroniP,double bias,double lower,double upper,double adjustedSignificance,double adjustedCritical,double adjustedLower,double adjustedUpper,double percentileLower,double percentileUpper,boolean intervalAvailable,boolean adjustedIntervalRejects,boolean referenceSmallError,EmpiricalHistogram histogram,double[] distribution){public Term{distribution=distribution.clone();}@Override public double[] distribution(){return distribution.clone();}}
    public record Block(String name,int[] columns,int fullTetradCount,int genericOneFactorCodimension,List<Term> terms,boolean rejectsReflective,List<String> warnings){public Block{columns=columns.clone();terms=List.copyOf(terms);warnings=List.copyOf(warnings);}@Override public int[] columns(){return columns.clone();}}
    public record Result(Options options,int observations,int successful,int failed,Map<String,Integer> failures,List<Block> blocks,List<String> skipped,List<String> warnings){public Result{failures=Collections.unmodifiableMap(new LinkedHashMap<>(failures));blocks=List.copyOf(blocks);skipped=List.copyOf(skipped);warnings=List.copyOf(warnings);}}
    public static List<Tetrad> tetrads(int p,Selection selection){
        if(p<4||p>25)throw new IllegalArgumentException("Tetrad blocks need 4–25 indicators.");List<Tetrad> all=new ArrayList<>();int id=1;for(int a=0;a<p-3;a++)for(int b=a+1;b<p-2;b++)for(int c=b+1;c<p-1;c++)for(int d=c+1;d<p;d++){all.add(new Tetrad(id++,a,b,c,d));all.add(new Tetrad(id++,a,b,d,c));all.add(new Tetrad(id++,a,c,d,b));}if(selection==Selection.ALL_TETRADS)return List.copyOf(all);if(selection==Selection.CANONICAL_BASIS)return all.stream().filter(t->t.a()==0&&t.b()==1&&(t.c()<t.d()||t.d()==2)).toList();try(var stream=TetradAnalysis.class.getResourceAsStream("/cta-reference-bases.json")){if(stream==null)throw new IllegalStateException("Tetrad reference subset resource is missing.");var entries=JsonParser.parseReader(new InputStreamReader(stream,StandardCharsets.UTF_8)).getAsJsonObject().getAsJsonArray(Integer.toString(p));List<Tetrad> result=new ArrayList<>();for(var entry:entries){var value=entry.getAsJsonObject();var columns=value.getAsJsonArray("columns");var tetrad=new Tetrad(value.get("id").getAsInt(),columns.get(0).getAsInt(),columns.get(1).getAsInt(),columns.get(2).getAsInt(),columns.get(3).getAsInt());if(!all.get(tetrad.id()-1).equals(tetrad))throw new IllegalStateException("Tetrad reference subset identity differs.");result.add(tetrad);}return List.copyOf(result);}catch(IOException problem){throw new IllegalStateException("Cannot read tetrad subset.",problem);}
    }
    public static Result fit(double[][] observations,List<String> names,List<PlsSem.Block> supplied,Options options,IntConsumer progress){
        int p=Matrices.width(observations,3),n=observations.length;List<PlsSem.Block> models=new ArrayList<>();List<List<Tetrad>> definitions=new ArrayList<>();List<String> skipped=new ArrayList<>(),warnings=new ArrayList<>();Set<String> blockNames=new HashSet<>();int count=0;for(var block:supplied){if(block.name().isBlank()||!blockNames.add(block.name()))throw new IllegalArgumentException("Tetrad block names must be distinct and nonblank.");int[] columns=block.columns();Set<Integer> unique=new HashSet<>();for(int column:columns)if(column<0||column>=p||!unique.add(column))throw new IllegalArgumentException("Invalid tetrad indicator assignment.");if(columns.length<4||columns.length>25){skipped.add(block.name()+": requires 4–25 indicators; found "+columns.length);continue;}var tetrads=tetrads(columns.length,options.selection());models.add(block);definitions.add(tetrads);count+=tetrads.size();}if(names.size()!=p||names.stream().anyMatch(name->name==null||name.isBlank())||new HashSet<>(names).size()!=p)throw new IllegalArgumentException("Tetrad indicator names differ from data.");if(models.isEmpty())throw new IllegalArgumentException("No measurement block has 4–25 indicators.");if((long)count*options.samples()>10000000L||count>20000)throw new IllegalArgumentException("Tetrad bootstrap storage exceeds the current limit; reduce samples, block count or tetrad selection.");
        double[] point=new double[count];int offset=0;for(int block=0;block<models.size();block++){double[][] covariance=covariance(observations,models.get(block).columns(),null);for(int j=0;j<covariance.length;j++)if(!(covariance[j][j]>0))throw new IllegalArgumentException("Tetrad analysis requires nonconstant original indicators.");for(var tetrad:definitions.get(block))point[offset++]=value(covariance,tetrad);}double[][] draws=new double[options.samples()][];Random random=new Random(options.seed());boolean reference=options.convention()==RegressionBootstrap.Convention.REFERENCE_4_1_2_1;long[] seeds=reference?ReferenceResampling.seeds(options.seed(),options.samples()):null;int successful=0;Map<String,Integer> failures=new LinkedHashMap<>();
        for(int sample=0;sample<options.samples();sample++){Matrices.interrupted();int[] rows=reference?ReferenceResampling.rows(seeds[sample],n):Bootstrap.draw(random,n);try{double[] estimates=new double[count];offset=0;for(int block=0;block<models.size();block++){double[][] covariance=covariance(observations,models.get(block).columns(),rows);for(var tetrad:definitions.get(block))estimates[offset++]=value(covariance,tetrad);}draws[successful++]=estimates;}catch(IllegalArgumentException|ArithmeticException problem){String reason=problem.getMessage()==null?problem.getClass().getSimpleName():problem.getMessage();failures.merge(reason,1,Integer::sum);}if(progress!=null)progress.accept(sample+1);}
        if(successful<Math.max(30,(int)Math.ceil(options.samples()*.8)))throw new IllegalArgumentException("Fewer than 30 and 80% usable tetrad bootstrap samples: "+failures);List<Block> results=new ArrayList<>();offset=0;var normal=new NormalDistribution();for(int block=0;block<models.size();block++){
            List<Term> terms=new ArrayList<>();List<String> blockWarnings=new ArrayList<>();var definition=definitions.get(block);double adjustedAlpha=options.significance()/definition.size();if(options.selection()==Selection.CANONICAL_BASIS){double[][] sample=covariance(observations,models.get(block).columns(),null);for(int[] pair:new int[][]{{0,1},{0,2},{1,2}})if(Math.abs(sample[pair[0]][pair[1]])<=1e-12*Math.sqrt(sample[pair[0]][pair[0]]*sample[pair[1]][pair[1]])){blockWarnings.add("Canonical basis has a zero/negligible anchor covariance; its generic algebraic equivalence may degenerate. Inspect all tetrads before interpreting nonrejection.");break;}}if(options.selection()==Selection.ALL_TETRADS)blockWarnings.add("All tetrads include algebraic redundancies. Bonferroni uses every reported test and is more conservative than a basis.");if(options.selection()==Selection.REFERENCE_SUBSET&&models.get(block).columns().length==14)blockWarnings.add("The recovered 14-indicator subset contains 78 tests; its regular one-factor Jacobian rank is 77. Compatibility retains this redundant test and its 78-test Bonferroni denominator.");
            for(var tetrad:definition){Matrices.interrupted();double original=point[offset];double[] distribution=new double[successful];double mean=0,ss=0;for(int sample=0;sample<successful;sample++){double draw=draws[sample][offset];distribution[sample]=draw;double delta=draw-mean;mean+=delta/(sample+1);ss+=delta*(draw-mean);}double sd=Math.sqrt(Math.max(0,ss/(reference?successful:successful-1))),bias=mean-original,statistic=Double.NaN,probability=Double.NaN;if(!Double.isFinite(sd)||!Double.isFinite(mean))throw new IllegalArgumentException("Tetrad uncertainty exceeds numeric range; rescale the indicators.");boolean small=reference&&Math.abs(sd)<=1e-11;if(small){statistic=0;probability=options.twoSided()?1:.5;}else if(sd>0){statistic=Math.abs(original/sd);probability=reference?ReferenceDistributions.tTwoSided(statistic,options.samples())/(options.twoSided()?1:2):2*normal.cumulativeProbability(-statistic);}double critical=reference?ReferenceDistributions.tCritical(options.significance()*(options.twoSided()?1:2),options.samples()):normal.inverseCumulativeProbability(1-options.significance()/2),adjustedCritical=reference?ReferenceDistributions.tCritical(adjustedAlpha*(options.twoSided()?1:2),options.samples()):normal.inverseCumulativeProbability(1-adjustedAlpha/2);boolean available=(sd>0||reference)&&Double.isFinite(critical)&&Double.isFinite(adjustedCritical);double lower=available?original-bias-critical*sd:Double.NaN,upper=available?original-bias+critical*sd:Double.NaN,adjustedLower=available?original-bias-adjustedCritical*sd:Double.NaN,adjustedUpper=available?original-bias+adjustedCritical*sd:Double.NaN;double[] sorted=distribution.clone();Arrays.sort(sorted);int[] columns=models.get(block).columns();String label=names.get(columns[tetrad.a()])+", "+names.get(columns[tetrad.b()])+", "+names.get(columns[tetrad.c()])+", "+names.get(columns[tetrad.d()]);terms.add(new Term(tetrad,label,original,mean,sd,statistic,probability,Double.isFinite(probability)?Math.min(1,probability*definition.size()):Double.NaN,bias,lower,upper,adjustedAlpha,adjustedCritical,adjustedLower,adjustedUpper,Inference.quantile(sorted,options.significance()/2),Inference.quantile(sorted,1-options.significance()/2),available,available&&(adjustedLower>0||adjustedUpper<0),small,EmpiricalHistogram.of(distribution),options.retainDraws()?distribution:new double[0]));offset++;}
            if(terms.stream().anyMatch(Term::referenceSmallError))blockWarnings.add("Reference compatibility sets t=0 when bootstrap SD is at most 1e-11, regardless of the point estimate. Do not interpret this as evidence supporting reflectivity.");if(terms.stream().anyMatch(term->!term.intervalAvailable()))blockWarnings.add("At least one confidence interval is unavailable because uncertainty is degenerate; no acceptance of reflectivity follows.");int size=models.get(block).columns().length;results.add(new Block(models.get(block).name(),models.get(block).columns(),size*(size-1)*(size-2)*(size-3)/8,size*(size-3)/2,terms,terms.stream().anyMatch(Term::adjustedIntervalRejects),blockWarnings));
        }
        if(successful<options.samples())warnings.add("Failed paired samples were not replaced; reported inference conditions on the retained samples: "+failures);if(options.samples()<1000)warnings.add("Small bootstrap run; tail and multiple-test inference can be unstable.");if(!options.twoSided())warnings.add("Reference one-tailed compatibility uses absolute t and a symmetric narrower interval. The observed sign was not a prespecified directional alternative.");warnings.add("Blocks are assessed individually using raw population covariances. No PLS fit is needed. Bonferroni correction is within each block, not across every block. Adjusted bias-corrected intervals define the block rejection; the point/SD p-value can differ from that interval decision.");warnings.add("Rejecting vanishing tetrads challenges the specified reflective model; nonrejection does not prove reflectivity, formative causality or adequate power. Review theory, correlated errors, distributional assumptions and degeneracy.");return new Result(options,n,successful,options.samples()-successful,failures,results,skipped,warnings);
    }
    private static double value(double[][] covariance,Tetrad t){double value=covariance[t.a()][t.b()]*covariance[t.c()][t.d()]-covariance[t.a()][t.c()]*covariance[t.b()][t.d()];if(!Double.isFinite(value))throw new IllegalArgumentException("Tetrad exceeded finite numeric range.");return value;}
    private static double[][] covariance(double[][] data,int[] columns,int[] rows){int n=rows==null?data.length:rows.length,p=columns.length;double[] means=new double[p];for(int i=0;i<n;i++){if((i&255)==0)Matrices.interrupted();double[] row=data[rows==null?i:rows[i]];for(int j=0;j<p;j++)means[j]+=(row[columns[j]]-means[j])/(i+1);}double[][] result=new double[p][p];for(int i=0;i<n;i++){if((i&255)==0)Matrices.interrupted();double[] row=data[rows==null?i:rows[i]];for(int a=0;a<p;a++)for(int b=0;b<=a;b++)result[a][b]+=(row[columns[a]]-means[a])*(row[columns[b]]-means[b])/n;}for(int a=0;a<p;a++)for(int b=0;b<=a;b++){if(!Double.isFinite(result[a][b]))throw new IllegalArgumentException("Tetrad covariance exceeded finite numeric range.");result[b][a]=result[a][b];}return result;}
}
